// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.recordingimport android.content.Contextimport android.telephony.TelephonyManagerimport timber.log.Timberimport java.util.Locale/** * NOUS — Recording Legal Notice (Module 11 v3 — P1). * * Strategy §"CallRecordingEngine": "Legal notice: play TTS 'This call is * being recorded for your reference' at start of recording (if legally * required in user's region — check Locale/SimCountryIso)". * * ## Two-party consent states * * Many jurisdictions (e.g., California, Florida, India, EU) require all * parties to consent before a call can be recorded. NOUS plays an audible * notice at the start of every recording in those regions. * * ## How region is detected * *  1. `TelephonyManager.getSimCountryIso()` — the SIM's registered country. *  2. `Locale.getDefault().country` — device locale's country. *  3. If either matches a two-party-consent country → notice is required. * * The notice is read aloud via the injected [NoticeSpeaker] (typically * Module 5's EmotionalTtsEngine) — wired by [com.roshan.persona.connectivity.di.ConnectivityModule]. *//** * Countries that legally require two-party consent for call recording. * * Source: Wikipedia "Telephone recording laws" — countries that mandate * "all-party consent" (vs. one-party consent). * * ISO 3166-1 alpha-2 codes. */val TWO_PARTY_CONSENT_COUNTRIES: Set<String> = setOf(    "US",  // United States (11 states require all-party consent: CA, CT, FL, IL, MD, MA, MT, NV, NH, PA, WA)    "CA",  // Canada    "IN",  // India ( Telegraph Act §25 — requires consent)    "AU",  // Australia (some states)    "BR",  // Brazil    "DE",  // Germany    "FR",  // France    "IT",  // Italy    "ES",  // Spain    "NL",  // Netherlands    "PL",  // Poland    "RO",  // Romania    "TR",  // Turkey    "MX",  // Mexico    "AR",  // Argentina    "CL",  // Chile    "CO",  // Colombia    "PE",  // Peru    "VE",  // Venezuela)/** * Detects whether the user is in a two-party-consent region. */class RecordingLegalNotice(    private val context: Context,) {    /**     * True if the user's SIM country OR device locale country requires     * two-party consent for call recording.     */    fun isNoticeRequired(): Boolean {        return try {            val simCountry = getSimCountryIso()            val localeCountry = Locale.getDefault().country            val simMatch = simCountry != null && simCountry.uppercase() in TWO_PARTY_CONSENT_COUNTRIES            val localeMatch = localeCountry.uppercase() in TWO_PARTY_CONSENT_COUNTRIES            simMatch || localeMatch        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "isNoticeRequired failed — assume required for safety")            true // Fail-safe — play the notice if we can't determine.        }    }    /**     * Speak the legal notice via [speaker] if required.     *     * @return true if the notice was spoken, false if not required.     */    fun speakNoticeIfRequired(speaker: NoticeSpeaker): Boolean {        if (!isNoticeRequired()) return false        speaker.speak(NOTICE_TEXT)        return true    }    private fun getSimCountryIso(): String? {        return try {            val tm = context.getSystemService(Context.TELEPHONY_SERVICE) as? TelephonyManager                ?: return null            tm.simCountryIso?.takeIf { it.isNotBlank() }        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "getSimCountryIso failed")            null        }    }    private companion object {        private const val TAG = "RecordingLegalNotice"        private const val NOTICE_TEXT =            "This call is being recorded for your reference."    }}/** * TTS speaker interface for the recording legal notice. * * Real implementation is wired by [com.roshan.persona.connectivity.di.ConnectivityModule] * to delegate to Module 5's EmotionalTtsEngine. */fun interface NoticeSpeaker {    fun speak(text: String)}